interfaces.signature:
interface RecordingPanelProps {
  content: RecordingPanelContent;
  phase: RecordingPhase;
  durationLabel: string;
  message: string;
  saving?: boolean;
  recordedAudio?: CapturedAudio | null;
  actions: {
    toggle: () => void;
    retry: () => void; // 다시 녹음
    save: () => void;  // 저장 및 저장 재시도
  };
}

// RecordingPanelProps에 선택 입력 추가
saveLabel?: string; // 기본값 "저장하기"

// RolePlayRecordingClient에서 전달
saveLabel={session.saveFailed
  ? "다시 저장하기"
  : "저장하기"}

// RecordingPanel: saving이 우선
{saving ? "저장 중" : saveLabel}

interface CapturedAudio {
  readonly blob: Blob;
  readonly mimeType: SupportedAudioMimeType;
  readonly extension: SupportedAudioExtension;
  readonly durationMs: number;
}

saveRecording?: (audio: CapturedAudio) => Promise<void>;
saveLearnerRecording(audio: CapturedAudio, lineId: string): Promise<void>;

interface RecordingSessionBaseState {
  phase: RecordingPhase;
  currentStep: number;
  elapsedMs: number;
  saving: boolean;
  saveFailed: boolean;
}

saveFailure() → {
  phase: "recorded",
  saving: false,
  saveFailed: true
} // currentStep은 변경하지 않음
